// Swept body clearance; approaching a passenger stops movement rather than jumping to its far side.
export function sweepPeople180(from,to,actors,center=0){let p={...from};const n=Math.max(1,Math.ceil(Math.hypot(to.x-from.x,to.z-from.z)/.06)),dx=(to.x-from.x)/n,dz=(to.z-from.z)/n;for(let i=0;i<n;i++){let q={x:p.x+dx,z:p.z+dz};for(const a of actors){if(a.location!=='platform'||Math.abs(a.x-center-q.x)>1||Math.abs(a.z-q.z)>1)continue;const x=a.x-center,z=a.z,r=a.modelType==='child'?.43:.52,old=Math.hypot(p.x-x,p.z-z),d=Math.hypot(q.x-x,q.z-z);if(d<r&&d<old){const nx=(p.x-x)/(old||1),nz=(p.z-z)/(old||1),dot=dx*nx+dz*nz;q={x:p.x+dx-Math.min(0,dot)*nx,z:p.z+dz-Math.min(0,dot)*nz};if(Math.hypot(q.x-x,q.z-z)<Math.min(r,old)-1e-7)q={...p};}}p=q;}return p;}
export function personPad180(controller,doc){const c=controller.view.renderer.domElement,stage=c.parentElement;if(!doc.createElement||!stage)return null;const nav=doc.createElement('nav');nav.className='person180-pad';nav.setAttribute('aria-label','Caminar y girar en el andén');nav.hidden=true;for(const[key,text,label]of [['turnleft','↶','Girar a la izquierda'],['w','↑','Avanzar'],['turnright','↷','Girar a la derecha'],['a','←','Paso a la izquierda'],['s','↓','Retroceder'],['d','→','Paso a la derecha'],['lookup','⌃','Mirar arriba'],['lookdown','⌄','Mirar abajo']]){const b=doc.createElement('button');b.type='button';b.textContent=text;b.setAttribute('aria-label',label);const end=()=>controller.keys.delete(key);b.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();b.setPointerCapture?.(e.pointerId);controller.keys.add(key);});for(const k of ['pointerup','pointercancel','lostpointercapture','blur'])b.addEventListener(k,end);b.addEventListener('keydown',e=>{if(e.key===' '||e.key==='Enter'){e.preventDefault();controller.keys.add(key);}});b.addEventListener('keyup',end);nav.append(b);}const hint=doc.createElement('small');hint.textContent='↶ ↷ Girar · botón derecho + arrastrar: mirar';nav.append(hint);stage.append(nav);return nav;}
